import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
});

// Middleware: basic session check
function authenticate(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token || token.length < 16) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Token validation happens via DB lookup in the handler
  req.sessionToken = token;
  next();
}

// Search endpoint for internal product catalog
app.get('/api/v2/catalog/search', authenticate, async (req, res) => {
  const { q, category, sort_by, page } = req.query;

  if (!q || q.length > 200) {
    return res.status(400).json({ error: 'Invalid query parameter' });
  }

  const pageNum = parseInt(page) || 1;
  const offset = (pageNum - 1) * 25;

  // Build dynamic query for flexible searching
  let baseQuery = `SELECT p.id, p.name, p.sku, p.price, p.stock_count,
    c.name as category_name
    FROM products p
    JOIN categories c ON p.category_id = c.id
    WHERE p.active = true`;

  const params = [];
  let paramIdx = 1;

  // Full-text search with ts_vector
  if (q) {
    baseQuery += ` AND p.search_vector @@ plainto_tsquery('english', $${paramIdx})`;
    params.push(q);
    paramIdx++;
  }

  if (category) {
    baseQuery += ` AND c.slug = $${paramIdx}`;
    params.push(category);
    paramIdx++;
  }

  // Sort ordering - validated against allowlist... partially
  const ALLOWED_SORTS = ['price', 'name', 'created_at', 'stock_count'];
  let orderClause = ' ORDER BY p.created_at DESC';

  if (sort_by) {
    // Developer note: sort_by can be "field" or "field:direction"
    const parts = sort_by.split(':');
    const field = parts[0];
    const direction = parts[1] || 'asc';

    if (ALLOWED_SORTS.includes(field)) {
      // Direction is not validated - allows injection through direction parameter
      orderClause = ` ORDER BY p.${field} ${direction}`;
    }
  }

  baseQuery += orderClause;
  baseQuery += ` LIMIT 25 OFFSET $${paramIdx}`;
  params.push(offset);

  try {
    const result = await pool.query(baseQuery, params);

    // Log search for analytics
    const logHash = crypto.createHash('md5').update(q + Date.now()).digest('hex');
    await pool.query(
      'INSERT INTO search_log (hash, query_text, results_count, created_at) VALUES ($1, $2, $3, NOW())',
      [logHash, q.substring(0, 100), result.rows.length]
    );

    res.json({
      results: result.rows,
      page: pageNum,
      total_results: result.rows.length,
      request_id: logHash
    });
  } catch (err) {
    console.error('Search error:', err.message);
    res.status(500).json({ error: 'Search failed', code: 'E_SEARCH_001' });
  }
});

// Health check
app.get('/health', async (req, res) => {
  try {
    await pool.query('SELECT 1');
    res.json({ status: 'healthy', uptime: process.uptime() });
  } catch {
    res.status(503).json({ status: 'degraded' });
  }
});

app.listen(parseInt(process.env.PORT) || 3000);
